namespace ghidra.app.plugin.core.datamgr.actions;



using docking;
using docking.action;
using docking.action;
using docking.widgets.tree;
using docking.widgets.tree;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr.tree;
using ghidra.program.model.dtarchive;

/**
 * Action for saving a ProjectDataTypeArchive or a FileDataTypeArchive to a new storage location.
 */
public class SaveArchiveAsAction : DockingAction {
	private DataTypeManagerPlugin plugin;

	public SaveArchiveAsAction(DataTypeManagerPlugin plugin) : base("Save As", plugin.getName())
    {

		this.plugin = plugin;
		setPopupMenuData(new MenuData(new string[] { "Save Archive As..." }, "File"));
		setEnabled(true);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is DataTypesActionContext)) {
			return false;
		}

		object contextObject = context.getContextObject();
		GTree gtree = (GTree) contextObject;
		TreePath[] selectionPaths = gtree.getSelectionPaths();
		if (selectionPaths == null || selectionPaths.length != 1) {
			return false;
		}

		GTreeNode node = (GTreeNode) selectionPaths[0].getLastPathComponent();
		if (node is ArchiveNode) {
			return true;
		}

		return false;
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		GTree gtree = (GTree) context.getContextObject();
		ArchiveManager archiveManager = plugin.getArchiveManager();
		TreePath[] selectionPaths = gtree.getSelectionPaths();
		ArchiveNode node = (ArchiveNode) selectionPaths[0].getLastPathComponent();
		PersistentDataTypeArchive archive = node.getArchive();

		archiveManager.saveAs(archive);
		if (archive is FileDataTypeArchive fa) {
			plugin.addRecentlyOpenedArchiveFile(fa.getFile());
		}
		else if (archive is ProjectDataTypeArchive pa) {
			plugin.addRecentlyOpenedProjectArchive(pa);
		}
	}
}
